// Keep only suspects whose excerpt really appears in a file the agent read.
const result = $input.first().json.output;
if (!result || typeof result !== 'object') return [{ json: { investigation: null } }];
const norm = s => String(s || '').replace(/\s+/g, ' ').trim();
const reads = {};
for (const step of $input.first().json.intermediateSteps || []) {
  if (step.action?.tool !== 'read_repo_file') continue;
  let args = step.action.toolInput;
  if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
  const key = `${args.repository || 'backend'}:${args.file_path}`;
  reads[key] = (reads[key] || '') + ' ' + norm(typeof step.observation === 'string' ? step.observation : JSON.stringify(step.observation));
}
const suspects = (result.suspects || []).filter(s =>
  s.excerpt && (reads[`${s.repository}:${s.path}`] || '').includes(norm(s.excerpt)));
const dropped = (result.suspects || []).length - suspects.length;
const investigation = {
  likely_cause: result.likely_cause,
  suspects,
  suggested_fix: result.suggested_fix,
  // Unverified citations lower the confidence.
  confidence: suspects.length ? Math.min(result.confidence ?? 0, dropped ? 0.5 : 1) : Math.min(result.confidence ?? 0, 0.3),
  checked_at: new Date().toISOString(),
};
return [{ json: { investigation } }];

function investigationLines(raw) {
  let inv = raw;
  if (typeof inv === 'string') { try { inv = JSON.parse(inv); } catch (e) { inv = null; } }
  if (!inv || !inv.likely_cause) return [];
  const level = inv.confidence >= 0.7 ? 'بالا' : inv.confidence >= 0.4 ? 'متوسط' : 'پایین';
  return [
    '\u0000',
    `🔍 بررسی کد (حدس، نیاز به تأیید — اطمینان ${level}):`,
    `علت احتمالی: ${inv.likely_cause}`,
    ...(inv.suspects || []).slice(0, 3).map(s => `• ${s.repository}: ${s.path}${s.symbol ? ` (${s.symbol})` : ''} — ${s.why || ''}`),
    inv.suggested_fix && `پیشنهاد رفع: ${inv.suggested_fix}`,
  ];
}
function formatIssueMessage({ kind, row, c, triage, photos, edited, incomplete }) {
  const TEAM = { backend: 'بک‌اند', frontend: 'فرانت‌اند', devops: 'دواپس' };
  const PRIORITY = { critical: '🔴 بحرانی', high: '🟠 بالا', medium: '🟡 متوسط', low: '🟢 پایین' };
  const BREAK = '\u0000';
  const list = value => (Array.isArray(value) ? value.filter(Boolean).join('، ') : value || '');
  const ids = (c.collected_identifiers || []).map(i => `${i.name}: ${i.value}`).join('، ');
  const team = TEAM[row.team] || row.team || 'نامشخص';
  const repeats = String(kind || '').startsWith('repeat:') ? kind.split(':')[1] : row.case_count;
  const lines = [
    kind === 'new' ? `🆕 مشکل جدید برای تیم ${team}` : `🔁 این مشکل به ${repeats} گزارش رسید (تیم ${team})`,
    `«${row.title}»`,
    `کد: ${row.issue_key} | اولویت: ${PRIORITY[row.priority] || row.priority || '-'}`,
    `قابلیت: ${row.feature_name || '-'} | بخش کد: ${row.modules || '-'}`,
    `تعداد گزارش‌ها: ${row.case_count || 1}`,
    BREAK,
    c.description && `شرح: ${c.description}`,
    c.actual_behavior && `اتفاق فعلی: ${c.actual_behavior}`,
    c.expected_behavior && `انتظار: ${c.expected_behavior}`,
    list(c.error_messages) && `خطا: ${list(c.error_messages)}`,
    list(c.steps_to_reproduce) && `مراحل: ${list(c.steps_to_reproduce)}`,
    c.affected_user_id && `مشتری: ${c.affected_user_id}`,
    ids && `شناسه‌ها: ${ids}`,
    c.occurred_at && `زمان: ${c.occurred_at}`,
    c.environment && `محیط: ${c.environment}`,
    photos && `تصویر: ${photos}`,
    triage?.team_reason && `دلیل انتخاب تیم: ${triage.team_reason}`,
    ...investigationLines(row.investigation),
    (edited || incomplete) && BREAK,
    incomplete && '⏳ پشتیبانی در حال تکمیل اطلاعات این گزارش است.',
    edited && `✏️ به‌روزرسانی شد: ${edited}`,
  ].filter(Boolean).map(line => (line === BREAK ? '' : line));
  return lines.join('\n').slice(0, 4000);
}

const input = $('Confirmed Issue').first().json;
const output = input.output;
const stored = $('Load Issue').all().map(item => item.json).find(r => r.issue_key === input.issue_key) || {};
const investigation = $('Verify Investigation').first().json.investigation;
if (!investigation) return [];
const triage = output.triage || {};
const row = {
  issue_key: input.issue_key,
  title: stored.title || output.issue?.title || '',
  team: stored.team || triage.team,
  priority: stored.priority || triage.priority,
  feature_name: stored.feature_name || output.case.feature_name,
  modules: stored.modules || '',
  case_count: Number(stored.case_count) || 1,
  investigation,
};
return $input.all().map(item => item.json).filter(ref => ref.message_id).map(ref => ({ json: {
  chat_id: String(ref.chat_id),
  message_id: ref.message_id,
  text: formatIssueMessage({ kind: ref.kind, row, c: output.case, triage, photos: output.photo_description || '' }),
} }));
